 $a=require_admin();
 if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed');}
 csrf_check();rate_limit('database_backup',5,3600);
 db()->exec('PRAGMA wal_checkpoint(FULL)');
 $path=database_path();
 if(!is_file($path)){http_response_code(404);exit('Database file not found.');}
 audit((int)$a['id'],'database_backup','system',null,['bytes'=>filesize($path)]);
 header('Content-Type: application/octet-stream');
 header('Content-Disposition: attachment; filename="securelink-backup-'.date('Y-m-d-His').'.sqlite"');
 header('Content-Length: '.filesize($path));
 header('Cache-Control: no-store');
 readfile($path);exit;
}

